    for s in g.iter('{%s}source'%ns['c']):
        if s.get('id')==src:
            a=np.array(s.find('c:float_array',ns).text.split(),float).reshape(-1,3)
    geoms[g.get('id')]=a
def walk(n,M,name):
    m=n.find('c:matrix',ns)
    if m is not None: M=M@np.array(m.text.split(),float).reshape(4,4)
    for ig in n.findall('c:instance_geometry',ns):
